  "please_provide_one_of": [
    "Phone number on the affected line",
    "Customer ID",
    "Full name AND date of birth (YYYY-MM-DD)"
  ],
  "questions": [
    "What is the phone number of the line that shows “No Service”?",
    "Are you traveling outside your usual area right now? If yes, where (city/country)?",
    "Did anything change recently (new SIM, plan change, late bill, device swap)?",
    "Do you see an airplane icon in the status bar?"
  ],
  "while_we_verify_try_these_steps": [
