      "step": "Toggle Airplane Mode",
      "why": "Forces the phone to fully reset its radio connection to the network.",
      "how": "Turn Airplane Mode ON for 20 seconds, then turn it OFF. Wait 1–2 minutes to see if signal returns."
    },
    {
      "step": "Reboot the phone",
      "why": "Refreshes all network services and clears temporary glitches.",
      "how": "Power the phone off completely, wait 30 seconds, then power it back on."
    },
    {
      "step": "Reseat the SIM (if comfortable)",
      "why": "A slightly mis-seated SIM can cause a complete loss of service.",
      "how": "Power off the phone. Eject the SIM tray, remove the SIM, check for dust, reinsert it snugly, and power the phone back on."
    }
  ],
  "what_to_report_back": [
    "Whether Airplane Mode was on or off",
    "Whether signal bars reappeared after the toggle/reboot",
    "Any SIM-related messages like “No SIM,” “SIM not provisioned,” or “SIM locked”"
