messages.content:
{
  "thought_process": "I’m going to tackle this on two fronts: (1) quick checks on your phone that commonly resolve a sudden “No Service” issue (like Airplane Mode or a SIM hiccup), and (2) checking your line status on our side (e.g., suspension from an overdue bill or other account flags). I’ll need to identify your account to run backend checks, while you do a couple of fast steps on the device. This approach minimizes downtime and helps pinpoint the cause.",
  "need_identification": {
    "please_provide_one_of": {
      "preferred": "phone_number_for_the_affected_line",
      "alternatives": [
        "customer_id",
        {
          "full_name": "exact legal name",
          "date_of_birth": "YYYY-MM-DD"
        }
      ]
    }
  },
  "questions": [
    "Is the issue everywhere you go or only in one location? If one spot, what city/ZIP?",
    "What phone model are you using (e.g., iPhone 13, Samsung S22)?",
    "Do you use a physical SIM or eSIM?",
    "Did anything change recently (new phone/SIM, software update, travel, dropped phone, etc.)?"
  ],
  "while_i_verify_on_our_side_please_try": [
    {
      "step": 1,
      "action": "Check Airplane Mode",
      "how": "Look for an airplane icon in the status bar or open quick settings. If it’s ON, turn it OFF. If it’s already OFF, toggle it ON for 10 seconds, then OFF again.",
      "why": "Airplane Mode disables all cellular radios; toggling forces a fresh network registration."
    },
    {
      "step": 2,
      "action": "Quick signal reset",
      "how": "Turn mobile data OFF for 10 seconds, then back ON. If you’re on Wi‑Fi, temporarily turn Wi‑Fi OFF for a moment to force the phone to try cellular again.",
      "why": "Forces the device to re-attempt cellular attachment."
    },
    {
      "step": 3,
      "action": "Check SIM status",
      "how": "If you can, open Settings > About/Cellular/SIM and confirm the SIM is detected (not Missing or Locked). If shown Missing/Not detected, power off, remove and reinsert the SIM carefully, then power on. If asked for a SIM PIN/PUK and you don’t have it, let me know.",
      "why": "A loose or locked SIM will cause “No Service.”"
    },
    {
      "step": 4,
      "action": "Optional quick reboot",
      "how": "Restart the phone (this takes 1–2 minutes).",
      "why": "Clears temporary radio stack glitches."
    }
  ],
  "next_steps_from_me": [
    "As soon as you share your identifying info, I’ll check your line status (active vs. suspended), any overdue bills, and roaming/plan flags.",
    "If I find a suspension due to billing, I’ll walk you through resolving it and immediately resume the line once cleared.",
    "If the line is active, I’ll guide deeper network checks (APN/SIM/eSIM provisioning) based on your device model."
  ],
  "request": "Please reply with the phone number for the affected line (or your customer ID, or your full name and date of birth in YYYY-MM-DD format), and let me know the results of steps 1–4 above."
}

