messages.content:
{
  "thought_process": "I looked up your line ending in 2002. Your account and line are Active, international roaming on your line is already enabled, and you’ve used 8.7 GB out of 15 GB this cycle (so you still have data available). Since you’re abroad and calls/SMS work, the most common MMS blockers are: mobile data or data roaming switch OFF on the phone, Wi‑Fi Calling interfering, or an incorrect MMSC/APN setting. We’ll first verify mobile data is working over the cellular network, then try a quick MMS test, and only then check APN if needed.",
  "account_checks": {
    "customer_id": "C1001",
    "line_id": "L1002",
    "status": "Active",
    "roaming_enabled_on_line": true,
    "plan": "Premium Plan 15 GB",
    "data_used_gb": 8.7,
    "data_limit_gb": 15
  },
  "steps": [
    {
      "title": "Turn off Wi‑Fi and verify status bar",
      "why": "MMS needs mobile data. We want to ensure the phone is actually on cellular data while you’re abroad.",
      "do_this": [
        "Please turn Wi‑Fi OFF (you can turn it back on later).",
        "Run check_status_bar and tell me what you see. Specifically: no Airplane icon, signal bars present, and a 4G/LTE/5G (or similar) indicator. Also note if it says 📱 Data Enabled or 📵 Data Disabled."
      ]
    },
    {
      "title": "Confirm mobile data and data roaming switches",
      "why": "Abroad, mobile data must be ON and Data Roaming must be ON on the phone.",
      "do_this": [
        "Run check_network_status and share the output for: signal strength, network type, Mobile Data (ON/OFF), and Data Roaming (ON/OFF).",
        "If Mobile Data is OFF, please use toggle_data to turn it ON.",
        "If Data Roaming is OFF, please use toggle_roaming to turn it ON."
      ]
    },
    {
      "title": "Test internet over mobile data",
      "why": "If a web page loads over mobile data, MMS prerequisites are met.",
      "do_this": [
        "With Wi‑Fi still OFF, try opening a simple website like example.com in your browser.",
        "Tell me whether it loads."
      ]
    },
    {
      "title": "Temporarily turn OFF Wi‑Fi Calling and test MMS",
      "why": "Some devices/carriers don’t handle MMS over Wi‑Fi Calling when roaming.",
      "do_this": [
        "Run check_wifi_calling_status. If it’s ON, please use toggle_wifi_calling to turn it OFF.",
        "Now try sending an MMS (a small photo) to a regular mobile number and tell me what happens."
      ]
    }
  ],
  "if_still_not_working_next": [
    {
      "title": "Check APN/MMSC",
      "do_this": [
        "Run check_apn_settings and share the APN name and MMSC URL.",
        "If MMSC is missing/incorrect, use reset_apn_settings, then reboot_device, and test MMS again."
      ]
    },
    {
      "title": "Ensure modern network mode",
      "do_this": [
        "Run check_network_mode_preference. If it shows 2G/3G only, set set_network_mode_preference to \"4g_5g_preferred\" and test again."
      ]
    },
    {
      "title": "Data Saver/VPN",
      "do_this": [
        "Run check_data_restriction_status; if Data Saver is ON, toggle_data_saver_mode OFF.",
        "Run check_vpn_status; if a VPN is connected, disconnect_vpn and retry MMS."
      ]
    },
    {
      "title": "Messaging app permissions",
      "do_this": [
        "Run check_app_permissions with app_name=\"messaging\". If storage or sms are not granted, grant_app_permission for storage and sms."
      ]
    }
  ],
  "please_share_back": [
    "The exact outputs from check_status_bar and check_network_status.",
    "Whether example.com loaded on mobile data.",
    "Wi‑Fi Calling status and the result of the MMS test.",
    "If we need to proceed, the APN name and MMSC URL values."
  ]
}

