  "message": "I’m sorry you’re having trouble with MMS. I can help. Here’s my plan: first I’ll verify your line/account status (e.g., any suspension, data cap, or roaming setting) and then we’ll run a few quick checks on your phone to rule out settings issues like data being off, network mode, APN/MMSC, Wi‑Fi Calling, or app permissions.",
  "what_i_need_from_you": {
    "identify_customer": "Please provide ONE of the following so I can look up your line:",
    "options": [
      "Phone number for the line with the MMS issue (preferred)",
      "OR your full name and date of birth (YYYY-MM-DD)",
      "OR your customer ID"
    ]
  },
  "quick_questions": [
    "Are regular calls and SMS texts working?",
    "Can you use mobile data for browsing if you turn Wi‑Fi off?",
    "Are you currently traveling outside your home network/country?",
    "Do MMS fail to send, receive, or both? Any error message?",
    "What phone do you have (Android or iPhone, model/version)?"
  ],
  "while_we_verify_the_account": {
    "please_run_these_checks_on_your_phone": [
      {
        "action": "check_status_bar",
        "instructions": "Tell me exactly what you see: Airplane Mode icon, signal bars (No Signal / 1–4 bars), network type (5G/4G/LTE/3G/2G), Mobile Data status (Data Enabled/Disabled), Wi‑Fi status, and any VPN icon."
      }
    ],
    "why_these_checks_help": "MMS needs working cellular service and mobile data. These checks quickly show if data is off, airplane mode is on, or if you’re on an unsuitable network type."
  }
}

