messages.content:
{
  "summary": "Your phone reports SIM Card Status: missing and No Service. That alone will prevent MMS (and all cellular data). First, we need your phone to detect the SIM again; then we’ll enable data roaming and test MMS.",
  "why_this_happens": "If the SIM isn’t detected, the phone cannot register to any network—so no calls/data/MMS (even if data is ON).",
  "next_steps": [
    {
      "step": 1,
      "title": "Reseat the SIM card",
      "reason": "Fixes most SIM detection issues.",
      "instructions": [
        "Power the phone OFF.",
        "Physically remove the SIM tray, take the SIM out, check for dust or debris, and gently reinsert it flush in the tray.",
        "Power the phone back ON.",
        "Action on device: check_sim_status — tell me the result (Active, Missing, or Locked).",
        "Action on device: check_network_status — tell me: signal bars, network type (5G/4G/3G/2G/none), and whether Mobile Data and Data Roaming show ON/OFF."
      ],
      "notes": [
        "If you use an eSIM instead of a physical SIM, let me know. We’ll adjust steps accordingly."
      ]
    },
    {
      "step": 2,
      "title": "If SIM becomes Active, enable data roaming (since you’re in France)",
      "only_if": "check_sim_status shows Active",
      "instructions": [
        "Action on device: toggle_roaming (turn Data Roaming ON).",
        "Action: check_network_status — confirm you now see some signal and a network type (ideally 4G/5G).",
        "Open a browser and try a website or run run_speed_test and share the result."
      ]
    },
    {
      "step": 3,
      "title": "Test MMS",
      "only_if": "You have signal and mobile data works",
      "instructions": [
        "Try sending an MMS (you can send a photo to your own number).",
        "If it fails, we’ll proceed to network mode and APN checks next."
      ]
    }
  ],
  "what_to_report_back": [
    "Result of check_sim_status after reseating (Active/Missing/Locked).",
    "Updated check_network_status readout (signal bars, network type, Mobile Data ON/OFF, Data Roaming ON/OFF).",
    "Whether browsing works or your run_speed_test result.",
    "What happens when you try sending an MMS."
  ],
  "if_other_outcomes": {
    "SIM_locked": {
      "what_you_may_see": "check_sim_status shows Locked or your phone asks for a SIM PIN/PUK.",
      "action": "Do not guess the PIN. Tell me what it shows. We’ll connect you with a human agent to securely assist with SIM security/PUK."
    },
    "SIM_still_missing": {
      "try_next": [
        "Action on device: reboot_device and then check_sim_status again.",
        "If possible, test your SIM in another phone OR test another known-good SIM in your phone to isolate whether it’s the SIM or the phone’s SIM tray/reader."
      ],
      "follow_up": "If it still shows Missing after these checks, the SIM may be damaged or the reader has an issue. Tell me the results and I’ll arrange next steps with a human agent if needed."
    }
  },
  "explanation_of_thought_process": "Since your account is active and roaming is enabled on our end, the SIM Missing status is the root cause of no service. Reseating the SIM is the fastest fix. Once the SIM is detected (Active), we’ll make sure your phone’s Data Roaming is ON (required abroad), verify mobile data works, and then test MMS. If MMS still fails after service/data are working, we’ll check network mode and APN/MMSC settings."
}

