      "step": 3,
      "title": "Verify the fix and test MMS",
      "instructions": [
        "Action: check_apn_settings — confirm an MMSC URL now appears.",
        "Action: check_network_status — confirm Mobile Data ON, Data Roaming ON, strong 4G/5G signal.",
        "Try sending an MMS to yourself and tell me what happens."
      ]
