messages.content:
{
  "context": "The 2 GB refuel is active, but your phone may still be using a stale data session or an MMS prerequisite may be blocking it. We’ll refresh your data connection, confirm you’re on 4G/5G, and verify MMS-related settings.",
  "what_to_do_now": [
    {
      "step": "1) Verify mobile data works (Wi‑Fi OFF)",
      "why": "MMS needs mobile data. We just added data, so this confirms the phone is actually using it.",
      "instructions": [
        "Turn Wi‑Fi OFF.",
        "Make sure Airplane mode is OFF.",
        "Ensure Mobile Data is ON.",
        "Open your browser and try loading example.com."
      ],
      "tell_me": "Does the webpage load? Also, what do you see near the signal bars (e.g., 5G/LTE/4G)?"
    },
    {
      "step": "2) Refresh the data session",
      "why": "Toggling forces the phone to establish a fresh data session after the refuel.",
      "instructions": [
        "Toggle Mobile Data OFF, wait 10 seconds, then ON.",
        "If still no luck, toggle Airplane Mode ON for 10 seconds, then OFF.",
        "Try sending an MMS again."
      ],
      "tell_me": "Did the MMS go through after toggling?"
    },
    {
      "step": "3) Ensure network mode isn’t limited to 2G/3G",
      "why": "MMS won’t work reliably on 2G. It should be set to prefer 4G/5G.",
      "instructions": [
        "Go to Settings > Network/Mobile network > Preferred network type.",
        "Select 4G/5G (often called 5G/4G/3G/2G auto or 4G/5G preferred).",
        "Retry sending an MMS."
      ],
      "tell_me": "What was the previous setting, and did MMS send after changing it?"
    },
    {
      "step": "4) Temporarily turn off Wi‑Fi Calling",
      "why": "On some setups, Wi‑Fi Calling can interfere with MMS.",
      "instructions": [
        "Go to Settings > Network & Internet (or Connections) > Mobile network > Wi‑Fi Calling.",
        "Turn Wi‑Fi Calling OFF.",
        "Retry sending an MMS."
      ],
      "tell_me": "Was Wi‑Fi Calling ON, and did turning it OFF help?"
    },
    {
      "step": "5) Reset APN to fix the MMSC (MMS server) settings",
      "why": "An incorrect or missing MMSC URL will block MMS. Resetting APN restores correct values.",
      "instructions": [
        "Go to Settings > Mobile network > Access Point Names.",
        "Open the active APN. If you’re unsure, tap the menu (⋮) and choose Reset to default.",
        "After resetting, restart the phone.",
        "When it powers back on, keep Wi‑Fi OFF and try sending an MMS."
      ],
      "tell_me": "Did you reset the APN and reboot? What happens when you try to send an MMS now?"
    },
    {
      "step": "6) Confirm Messages app permissions",
      "why": "The app needs Storage/Photos & videos and SMS permissions to handle MMS correctly.",
      "instructions": [
        "Go to Settings > Apps > Messages > Permissions.",
        "Allow: Photos and videos (or Storage) and SMS.",
        "Also in the app’s Mobile data settings, ensure Background data is allowed.",
        "Retry sending an MMS."
      ],
      "tell_me": "Were any permissions disabled? Did enabling them fix MMS?"
    }
  ],
  "if_no_data_detected_in_step_1": {
    "extra_refresh": [
      "Restart the phone.",
      "After restart, keep Wi‑Fi OFF, ensure Mobile Data is ON, load example.com, then retry MMS."
    ],
    "tell_me": "After the reboot, can you load a webpage and send an MMS?"
  },
  "next": "Please start with Step 1 now and share the results (does a webpage load, and what network icon you see like 5G/LTE/4G). I’ll guide you based on what you observe."
}

