    {
      "step": 1,
      "title": "Re‑check APN/MMSC after the reset",
      "why": "Sometimes the APN reset doesn’t populate MMSC on the first try, or the default profile lacks it.",
      "do_this": [
        "Open APN settings and run check_apn_settings.",
        "Confirm whether the MMSC URL is now present (not blank)."
      ],
      "branch": [
        "If MMSC is present: proceed to Step 2.",
        "If MMSC is still blank: proceed with Steps 2–6 first; if MMS still fails, I’ll escalate to provide the correct MMSC details."
      ]
    },
    {
      "step": 2,
      "title": "Turn OFF Wi‑Fi Calling (temporarily)",
      "do_this": [
        "Run check_wifi_calling_status.",
        "If it’s ON, run toggle_wifi_calling to turn it OFF.",
        "Try sending an MMS again."
      ]
    },
    {
      "step": 3,
      "title": "Ensure no VPN is active",
      "do_this": [
        "Run check_vpn_status.",
        "If connected, run disconnect_vpn.",
        "Try sending an MMS again."
      ]
    },
    {
      "step": 4,
      "title": "Disable Data Saver",
      "do_this": [
        "Run check_data_restriction_status.",
        "If Data Saver is ON, run toggle_data_saver_mode to turn it OFF.",
        "Try sending an MMS again."
      ]
    },
    {
      "step": 5,
      "title": "Verify messaging app permissions",
      "do_this": [
        "Run check_app_permissions for your default Messages app.",
        "If Storage or SMS is missing, run grant_app_permission for each missing one.",
        "Try sending an MMS again."
      ]
    },
    {
      "step": 6,
      "title": "Ensure background data for Messages is allowed",
      "do_this": [
        "Run check_app_status for your Messages app.",
        "If background data is restricted, change it to allowed.",
        "Try sending an MMS again."
      ]
    },
    {
      "step": 7,
      "title": "Reboot and test",
      "do_this": [
        "Run reboot_device.",
        "After the phone comes back up, keep Wi‑Fi OFF and send an MMS to yourself or a contact."
      ]
    }
  ],
  "please_reply_with": [
    "APN re-check: Is the MMSC URL now present or still blank?",
    "Wi‑Fi Calling status (now OFF or was already OFF).",
    "VPN status (connected or disconnected).",
    "Data Saver status (ON/OFF).",
    "Messaging app permissions (Storage and SMS granted?).",
    "Messages app background data (allowed or restricted).",
    "Whether MMS sent successfully after these steps."
  ],
  "next_action_if_needed": "If the MMSC remains blank after the APN reset and all other checks are OK, I’ll escalate so we can set the exact MMSC details for your device."
