    "is_it_safe_to_call": "Yes—completely safe. You won’t lose anything on your phone.",
    "do_i_need_mobile_data_for_calls": "No. Standard voice calls don’t require the Mobile Data switch. Mobile Data is needed for internet and MMS."
  },
  "steps_on_your_android": [
    {
      "step": "1) Place a quick call (safe to do)",
      "how": "Dial any number (a local French number is fine) and see if it connects. You do NOT need to turn on Mobile Data for this.",
      "why": "Confirms your line is registered on the local network for voice."
    },
    {
      "step": "2) Turn ON Mobile Data",
      "how": "Swipe down from the top twice to open Quick Settings > tap the Mobile Data icon to turn it ON. If you don’t see it: Settings > Network & Internet (or Connections) > Mobile Network (or SIMs) > toggle Mobile Data ON.",
      "why": "MMS and web browsing require Mobile Data to be ON."
    },
    {
      "step": "3) Turn ON Data Roaming",
      "how": "Settings > Network & Internet (or Connections) > Mobile Network > toggle Data Roaming ON.",
      "why": "You’re in France; roaming must be ON for data to work abroad. I already enabled roaming on your account; this turns it on in the phone."
    },
    {
      "step": "4) Keep Wi‑Fi OFF for this test",
      "how": "Make sure the Wi‑Fi icon is not showing in the status bar.",
      "why": "Ensures MMS uses mobile data."
    },
    {
      "step": "5) Test internet",
      "how": "Open your browser and go to google.com. Confirm the page loads.",
      "why": "Verifies mobile data is active."
    },
    {
      "step": "6) Try your picture message again",
      "how": "Send the MMS to one of your contacts.",
      "why": "With data restored and roaming enabled, it should send."
    }
