messages.content:
{
  "thought_process": "You’ve done the hard part—mobile data is now ON and you’re seeing 5G with signal bars. Since MMS still won’t send while abroad, the most common remaining culprit is APN settings (especially the MMSC part used by MMS). Resetting the APN to default plus a quick reboot usually fixes this. Before that, we’ll quickly confirm that general internet works on mobile data.",
  "empathy": "I understand this is frustrating. I’ll guide you step by step and stay with you through each step.",
  "plan": [
    "Do a quick internet test to see if mobile data is actually flowing.",
    "If web doesn’t load or MMS still fails, reset APN to default and restart the phone (this is safe and often resolves MMS while roaming).",
    "Verify a few settings (Wi‑Fi Calling, Data Saver, VPN, network mode) and retry the MMS."
  ],
  "step_by_step_android": [
    {
      "step": "1) Quick data test",
      "how": "Open your browser and go to google.com.",
      "expected": "If the page loads, mobile data works. If it doesn’t load, that points strongly to APN settings.",
      "tell_me": "Did google.com load?"
    },
    {
      "step": "2) Reset APN to default (safe)",
      "how": [
        "Open Settings.",
        "Tap Network & Internet (or Connections).",
        "Tap Mobile Network (or SIMs).",
        "Tap Access Point Names (APN).",
        "Tap the three‑dot menu (⋮) in the top‑right and choose Reset to default. Confirm."
      ],
      "why": "This restores the correct APN and MMSC info required for MMS, which often breaks while roaming."
    },
    {
      "step": "3) Restart the phone",
      "how": "Hold the power button > Restart.",
      "why": "APN changes only fully apply after a reboot."
    },
    {
      "step": "4) After restart: set the essentials",
      "how": [
        "Ensure Wi‑Fi is OFF for testing (no Wi‑Fi icon at the top).",
        "Make sure Mobile Data is ON.",
        "Make sure Data Roaming is ON: Settings > Network & Internet > Mobile Network > Data Roaming ON."
      ]
    },
    {
      "step": "5) Verify network mode",
      "how": "Settings > Network & Internet > Mobile Network > Preferred network type > choose 4G/5G (avoid 2G/3G).",
      "why": "MMS needs at least 3G; 4G/5G preferred is best."
    },
    {
      "step": "6) Optional checks (if available on your phone)",
      "how": [
        "Wi‑Fi Calling: turn it OFF temporarily: Settings > Network & Internet (or Calls & SMS) > Wi‑Fi Calling > OFF.",
        "Data Saver: turn it OFF: Settings > Network & Internet > Data Saver > OFF.",
        "VPN: if you see a key/VPN icon at the top, turn the VPN OFF: Settings > Network & Internet > VPN > Disconnect."
      ],
      "why": "These can interfere with MMS, especially when roaming."
    },
    {
      "step": "7) Test again",
      "how": [
        "Open your browser and go to google.com; confirm it loads.",
        "Then open your Messages app and try sending the photo again to one contact."
      ]
    }
  ],
  "voice_call_note": {
    "safe_to_call": "Yes, making a regular call is completely safe and won’t erase anything.",
    "optional_test": "If you’d like, place a quick call after Step 4. It’s not required for MMS but confirms voice service on the roaming network."
  },
  "what_to_report_back": [
    "Did google.com load before the APN reset?",
    "Were you able to Reset APN and Restart?",
    "After restart, is Mobile Data ON and Data Roaming ON?",
    "Did google.com load after the restart?",
    "Did the picture message send after these steps?",
    "If you tried a call, did it connect?"
  ],
  "offer_live_guidance": "If you prefer, tell me exactly what you see under Settings > Network & Internet > Mobile Network > Access Point Names, and I’ll guide you button‑by‑button in real time."
}

