messages.content:
{
  "assessment": "Service and data look good now (5G, roaming/data ON), so the remaining blockers for MMS are usually APN/MMSC configuration, Wi‑Fi Calling interference, Data Saver/VPN restrictions, or missing messaging app permissions.",
  "plan": [
    {
      "step": "Verify APN/MMSC",
      "actions": [
        "Run check_apn_settings and tell me what it reports for APN name and MMSC.",
        "If it shows Incorrect or MMSC missing, run reset_apn_settings.",
        "After resetting APN, run reboot_device to apply changes."
      ],
      "why": "MMS depends on a correct MMSC URL in APN settings. Incorrect/missing MMSC blocks MMS even when data works."
    },
    {
      "step": "Disable Wi‑Fi Calling (temporarily)",
      "actions": [
        "Run check_wifi_calling_status.",
        "If it is ON, run toggle_wifi_calling to turn it OFF."
      ],
      "why": "Wi‑Fi Calling can sometimes interfere with MMS when abroad."
    },
    {
      "step": "Check for data restrictions",
      "actions": [
        "Run check_data_restriction_status.",
        "If Data Saver is ON, run toggle_data_saver_mode to turn it OFF."
      ],
      "why": "Data Saver can block background data that MMS relies on."
    },
    {
      "step": "Rule out VPN issues",
      "actions": [
        "Run check_vpn_status.",
        "If a VPN is connected, run disconnect_vpn."
      ],
      "why": "Some VPNs can disrupt MMS/data routing."
    },
    {
      "step": "Confirm messaging app permissions",
      "actions": [
        "Run check_app_permissions with app_name=\"messaging\".",
        "If storage or sms permissions are missing, run grant_app_permission for each missing one (storage and sms)."
      ],
      "why": "The messaging app needs storage and SMS permissions to send MMS."
    },
    {
      "step": "Retest",
      "actions": [
        "With Wi‑Fi OFF and Mobile Data + Data Roaming ON, try sending a small photo MMS to yourself.",
        "Optionally, browse a website to confirm mobile data is active."
      ]
    }
  ],
  "what_to_report_back": [
    "check_apn_settings result (is MMSC present/correct?)",
    "Whether you reset APN and rebooted",
    "Wi‑Fi Calling status (now OFF?)",
    "Data Saver status (now OFF?)",
    "VPN status (disconnected?)",
    "Messaging app permissions (storage and sms granted?)",
    "Whether the MMS sent after these steps"
  ],
  "note": "Since you’re abroad and now on 5G with roaming enabled and extra data added, fixing APN/MMSC or disabling Wi‑Fi Calling usually resolves MMS quickly. Start with the APN/MMSC check and let me know the results."
}

