messages.content:
{
  "acknowledgement": "Thanks for sticking with this. You’re on 5G with excellent signal, roaming/data are ON, Wi‑Fi/Wi‑Fi Calling are OFF, and you already reset APN + rebooted. The most likely remaining blockers are device-side restrictions (Data Saver, VPN) or the messaging app’s permissions.",
  "thought_process": "MMS needs cellular data plus correct MMS settings. Since coverage, roaming, and APN are now good, we’ll rule out data restrictions and app-level permission issues. We’ll verify Data Saver and VPN aren’t interfering, then confirm the messaging app has storage and SMS permissions. Finally, we’ll run a quick MMS capability check.",
  "do_this_now_on_your_phone": [
    {
      "step": "Check Data Saver / Restrictions",
      "actions": [
        "Run: check_data_restriction_status",
        "If it reports Data Saver ON or background data restricted, run: toggle_data_saver_mode to turn it OFF."
      ],
      "why": "Data Saver can block MMS transfers in the background."
    },
    {
      "step": "Check VPN",
      "actions": [
        "Run: check_vpn_status",
        "If a VPN is connected, run: disconnect_vpn"
      ],
      "why": "Some VPNs interfere with MMS connectivity."
    },
    {
      "step": "Verify Messaging App Permissions",
      "actions": [
        "Run: check_app_permissions with app_name=\"messaging\"",
        "If \"storage\" is not granted, run: grant_app_permission with app_name=\"messaging\", permission=\"storage\"",
        "If \"sms\" is not granted, run: grant_app_permission with app_name=\"messaging\", permission=\"sms\""
      ],
      "why": "The messaging app needs storage (to access photos) and SMS/MMS permissions to send MMS."
    },
    {
      "step": "Quick Capability Check",
      "actions": [
        "Run: can_send_mms and share the result"
      ],
      "why": "Helps confirm whether the device stack now allows MMS."
    },
    {
      "step": "Test MMS",
      "actions": [
        "With Wi‑Fi and Wi‑Fi Calling still OFF, Mobile Data and Data Roaming ON, try sending a picture MMS to yourself or a contact."
      ],
      "why": "Confirms the fix under cellular data conditions."
    }
  ],
  "what_to_share_back": [
    "Output of check_data_restriction_status (is Data Saver ON/OFF).",
    "Output of check_vpn_status (connected or not).",
    "Output of check_app_permissions for app_name=\"messaging\" (which permissions are granted).",
    "Output of can_send_mms.",
    "Whether the MMS sends after these changes (or exactly what happens if it doesn’t)."
  ],
  "next_if_still_failing_after_these": [
    "We’ll review the APN readout with check_apn_settings to confirm the MMSC URL populated correctly after the reset.",
    "If needed, we’ll look at check_app_status for the messaging app to see if background data is restricted there and proceed accordingly."
  ]
}

