messages.content:
{
  "thought_process": "Since you just turned Airplane Mode OFF, seeing “No Signal” briefly can be normal while the phone re-registers on a roaming network in France. “Data Disabled” means the Mobile Data switch is OFF. Because MMS needs mobile data and roaming, we’ll turn those on and make sure your phone is set to use modern networks.",
  "what_to_do_now_on_android": [
    {
      "step": "Wait briefly",
      "how": "Give it 30–60 seconds to try to pick up a network after exiting Airplane Mode.",
      "reason": "Registration on a roaming partner can take a moment."
    },
    {
      "step": "Turn Mobile Data ON",
      "how": "Swipe down twice for Quick Settings > tap Mobile Data so it’s ON. Or Settings > Network & Internet (or Connections) > Mobile Network > Mobile Data = ON.",
      "reason": "Fixes the “Data Disabled” state so MMS can use cellular data."
    },
    {
      "step": "Turn Data Roaming ON",
      "how": "Settings > Network & Internet > Mobile Network > Data Roaming = ON.",
      "reason": "You’re in France; roaming must be ON on the phone. I’ve already enabled roaming on your line from our side."
    },
    {
      "step": "Ensure the SIM and network mode are correct",
      "how": [
        "Settings > Network & Internet > SIMs (or Mobile Network) > Make sure your active SIM for 555-123-2002 is toggled ON (Use SIM = ON).",
        "Settings > Network & Internet > Mobile Network > Preferred network type > select 5G/4G/3G (Auto) or 4G/5G preferred."
      ],
      "reason": "Ensures the phone can connect to modern networks abroad."
    },
    {
      "step": "Automatic network selection",
      "how": "Settings > Network & Internet > Mobile Network > Network operators > choose Select automatically.",
      "reason": "Lets the phone register to an available partner network in France."
    },
    {
      "step": "Check the status bar",
      "how": "Look for signal bars and a network type like 4G/LTE/5G. Keep Wi‑Fi OFF just for this test.",
      "reason": "Confirms you’re attached to a roaming network with data."
    },
    {
      "step": "Test MMS",
      "how": "Open your Messages app and send a photo to yourself.",
      "reason": "Verifies MMS once signal/data are available."
    }
  ],
  "if_you_still_see_no_signal": [
    "Toggle Airplane Mode ON, wait 10 seconds, then OFF again.",
    "Reboot the phone: hold Power > Restart.",
    "Check SIM status: Settings > About phone > SIM status. Tell me what it shows for Service state (e.g., In service, Out of service), Signal strength, and Network.",
