messages.content:
{
  "thought_process": "MMS needs at least a 3G/4G/5G data connection. You’re currently on 2G, which is too limited for MMS. Because you’re roaming in France, your phone likely latched onto a 2G-only network. We’ll switch your phone to prefer 4G/5G and, if needed, manually select a roaming partner that gives you 4G/LTE. Then we’ll test MMS. None of these steps will delete photos or messages.",
  "android_steps_to_move_off_2g": [
    {
      "step": "Set preferred network type to 4G/5G",
      "how": "Settings > Network & Internet (or Connections) > Mobile Network > Preferred network type > choose 5G/4G/3G (Auto) or 4G/5G preferred. If you see an option called Allow 2G, turn it OFF."
    },
    {
      "step": "Refresh the connection",
      "how": "Toggle Airplane mode ON for 10 seconds, then OFF. Wait ~30–60 seconds."
    },
    {
      "step": "Try automatic network first",
      "how": "Settings > Network & Internet > Mobile Network > Network operators > Select automatically = ON. Wait to see if it connects with 4G/LTE."
    },
    {
      "step": "If it still shows 2G, pick a network manually",
      "how": "Turn Select automatically OFF to scan. When the list appears, try a carrier and wait to register. In France you might see Orange F, SFR, Bouygues, Free. Try each until you get 4G/LTE next to your signal bars."
    },
    {
      "step": "Make sure data/roaming are on",
      "how": "Confirm Mobile Data = ON and Data Roaming = ON (same Mobile Network screen). Keep Wi‑Fi OFF just for this test."
    },
    {
      "step": "Test MMS",
      "how": "Open Messages and send a photo to yourself. If you use Wi‑Fi Calling, temporarily turn it OFF (Settings > Network & Internet > SIMs > Wi‑Fi Calling = OFF, or Phone app > Settings > Wi‑Fi Calling)."
    }
  ],
  "if_mms_still_fails_after_you_get_4g_lte": [
    {
      "step": "Reset APN to default (safe)",
      "how": "Settings > Network & Internet > Mobile Network > Access Point Names. Tap the menu ••• and choose Reset to default. Then Restart the phone. After restart, keep Wi‑Fi OFF briefly and try sending the photo again.",
      "reason": "Ensures the MMSC server setting for MMS is correct."
    },
    {
      "step": "Check data saver/VPN",
      "how": "Settings > Network & Internet > Data Saver = OFF. If you use a VPN, disconnect it and try again.",
      "reason": "These can interfere with data/MMS."
    }
  ],
  "reassurance": "Changing network settings, toggling Airplane mode, and resetting APN will not delete your photos or messages.",
  "what_to_report_back": [
    "After the steps above, what does the status bar show (e.g., 4G/LTE/5G or still 2G)?",
    "When you try sending the photo to yourself now, does it send, stay on “sending…”, or show “failed”?",
    "If you had to select a network manually, which one worked?"
  ]
}

