messages.content:
{
  "thought_process": "You now have strong 5G data, so the remaining common MMS blockers are: (1) Wi‑Fi Calling interfering, and/or (2) incorrect APN/MMSC settings. We’ll turn Wi‑Fi Calling OFF temporarily and then reset APN to defaults (safe) and reboot so the correct MMSC applies. Then we’ll test MMS again with Wi‑Fi OFF.",
  "steps_now_android": [
    {
      "step": "Turn Wi‑Fi OFF (just for testing)",
      "how": "Swipe down > tap Wi‑Fi to OFF."
    },
    {
      "step": "Turn Wi‑Fi Calling OFF (temporarily)",
      "how": "Settings > Network & Internet (or Connections) > SIMs/Mobile Network > Wi‑Fi Calling = OFF. If you don’t see it there, open the Phone app > Settings > Wi‑Fi Calling = OFF.",
      "reason": "Some roaming configurations can block MMS when Wi‑Fi Calling is ON."
    },
    {
      "step": "Reset APN to default (safe)",
      "how": "Settings > Network & Internet > Mobile Network > Access Point Names > tap the menu (⋮) > Reset to default.",
      "reason": "Ensures the MMSC server for MMS is correct."
    },
    {
      "step": "Restart the phone",
      "how": "Hold Power > Restart. Wait 1–2 minutes after it boots.",
      "reason": "Applies the refreshed APN/MMSC settings."
    },
    {
      "step": "Confirm basics after restart",
      "how": [
        "Settings > Network & Internet > SIMs/Mobile Network: Mobile Data = ON, Data Roaming = ON.",
        "Preferred network type = 5G/4G/3G (Auto) or 4G/5G preferred.",
        "Network operators = Select automatically."
      ]
    },
    {
      "step": "Test MMS",
      "how": "With Wi‑Fi still OFF and Wi‑Fi Calling OFF, open Messages and send a small photo to yourself. Watch for it to send.",
      "expect": "It should go through now that MMSC is correct and you’re on 4G/5G data."
    }
  ],
  "additional_checks_if_needed": [
    {
      "check": "Data Saver",
      "how": "Settings > Network & Internet > Data Saver = OFF."
    },
    {
      "check": "VPN",
      "how": "If you use a VPN, disconnect it and try again."
    },
    {
      "check": "Messaging app permissions",
      "how": "Settings > Apps > Messages (your SMS app) > Permissions: allow SMS and Storage/Photos & videos."
    }
  ],
  "reassurance": "Resetting APN and turning Wi‑Fi Calling OFF won’t delete any photos or messages. These are safe network settings changes.",
  "what_to_report_back": [
    "After the restart, does the status bar still show 4G/5G and good signal?",
    "Did the photo message send, stay on “sending…”, or show “failed”?",
    "If it failed, please tell me the exact error (if any) you see."
  ],
  "next_if_still_not_sending_after_all_steps": "Tell me and I’ll take the next step with you. If needed, I can transfer you to a human agent for deeper diagnostics, but let’s try the APN reset + reboot and Wi‑Fi Calling OFF first since these fix most MMS issues while roaming."
}

